changeSet.sql:
if exists(select * from INFORMATION_SCHEMA.TABLES where TABLE_SCHEMA = 'dbo' and TABLE_NAME = 'CommonQuery')
begin 
	exec sp_rename 'dbo.CommonQuery', 'CommonQuery_backup';
end

changeSet.rollback:
if exists(select * from INFORMATION_SCHEMA.TABLES where TABLE_SCHEMA = 'dbo' and TABLE_NAME = 'CommonQuery_backup')
begin 
 	exec sp_rename 'dbo.CommonQuery_backup', 'CommonQuery';
end
